item.aggregated_output:
ip address add 200.0.1.2/24 dev eth0
ip route add default via 200.0.1.1 dev eth0

# Web server reachable at http://200.0.1.2/.
mkdir -p /var/www/html
printf '%s\n' 'Internal web server' > /var/www/html/index.html
python3 -m http.server 80 --directory /var/www/html >/var/log/pc1-http.log 2>&1 &
ip address add 100.0.6.2/24 dev eth0
ip route add default via 100.0.6.1 dev eth0

# Authoritative-only server for the DNS root zone.
mkdir -p /etc/bind
cat > /etc/bind/named.conf <<'EOF'
options {
    directory "/var/cache/bind";
    listen-on { 100.0.6.2; };
    listen-on-v6 { none; };
    recursion no;
    allow-query { any; };
    dnssec-validation no;
};

zone "." {
    type master;
    file "/etc/bind/db.root.internal";
};
EOF

cat > /etc/bind/db.root.internal <<'EOF'
$TTL 300
@       IN SOA  ns.root. hostmaster.root. (
                2026092501 3600 900 604800 300 )
        IN NS   ns.root.
ns.root. IN A   100.0.6.2

test.   IN NS   ns.test.
ns.test. IN A   100.0.8.2
EOF

named-checkconf && named-checkzone . /etc/bind/db.root.internal && named -c /etc/bind/named.conf
ip address add 100.0.0.2/24 dev eth0
ip route add default via 100.0.0.1 dev eth0
ip address add 2001:8::2/64 dev eth0

# Recursive resolver.  Its only starting point is the internal root server.
mkdir -p /etc/bind
cat > /etc/bind/named.conf <<'EOF'
options {
    directory "/var/cache/bind";
    listen-on { 100.0.0.2; };
    listen-on-v6 { 2001:8::2; };
    recursion yes;
    allow-query { any; };
    allow-recursion { any; };
    dnssec-validation no;
};

zone "." {
    type hint;
    file "/etc/bind/db.root.internal";
};
EOF

cat > /etc/bind/db.root.internal <<'EOF'
.       300 IN NS ns.root.
ns.root. 300 IN A  100.0.6.2
EOF

named-checkconf && named-checkzone . /etc/bind/db.root.internal && named -c /etc/bind/named.conf
ip address add 200.0.6.2/24 dev eth0
ip route add default via 200.0.6.1 dev eth0

# Use only the internal recursive resolver.
printf '%s\n' 'nameserver 100.0.0.2' > /etc/resolv.conf
ip address add 100.0.8.2/24 dev eth0
ip route add default via 100.0.8.1 dev eth0

# Authoritative-only server for test.
mkdir -p /etc/bind
cat > /etc/bind/named.conf <<'EOF'
options {
    directory "/var/cache/bind";
    listen-on { 100.0.8.2; };
    listen-on-v6 { none; };
    recursion no;
    allow-query { any; };
    dnssec-validation no;
};

zone "test." {
    type master;
    file "/etc/bind/db.test";
};
EOF

cat > /etc/bind/db.test <<'EOF'
$TTL 300
@       IN SOA  ns.test. hostmaster.test. (
                2026092501 3600 900 604800 300 )
        IN NS   ns.test.
ns      IN A    100.0.8.2
www     IN A    200.0.1.2
EOF

named-checkconf && named-checkzone test. /etc/bind/db.test && named -c /etc/bind/named.conf
ip -6 address add 2001:8::1/64 dev eth0

# IPv6-only client: query pc3 over its IPv6 address.
printf '%s\n' 'nameserver 2001:8::2' > /etc/resolv.conf
/usr/local/bin/kathara
/Library/Frameworks/Python.framework/Versions/3.14/bin/python3
